import { addBook, updateBookNotes, getBook } from './lib/books.js';
const book = addBook({ title: 'Restart Check', author: 'Test Author', notes: '' });
updateBookNotes(book.id, 'Saved after creation.');
if (getBook(book.id)?.notes "'!== '"'Saved after creation.') throw new Error('Notes were not saved');
process.stdout.write(book.id);
