/bin/bash -lc "node --input-type=module <<'JS'
import { readFileSync, writeFileSync } from 'node:fs';
const file = 'data/books.json';
try {
  const books = JSON.parse(readFileSync(file, 'utf8'));
  const book = books.find((item) => item.title === 'Restart Check');
  if ("'!book) throw new Error('"'Book missing from JSON after restart');
  const response = await fetch("'`http://localhost:3000/books/${book.id}`);
  const html = await response.text();
  if (response.status !== 200 || !html.includes('"'Saved after creation.')) {
    throw new Error('Book or edited notes missing from page after restart');
  }
  process.stdout.write('PASS: book and edited notes survived server restart\\n');
} finally {
  writeFileSync(file, '[]\\n');
}
JS"
